  ('cpiuris2025::31a08bcef36ff3d174bb3a711417d756', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Garantia da Ordem Pública e Segregação Cautelar', '## Garantia da Ordem Pública e Segregação Cautelar

